{-| @Pudu.Backend.Emit.Entry — how a generated translation unit is entered,
    and what an emitted unit reports to the toolchain.

    The executable form is C `main`. The embedded form keeps the same body in a
    static function and exports `pudu_program_run`, which a host application
    calls; it flushes both standard streams before returning, since the host
    process keeps running after it. An atomic flag admits one run per process:
    the runtime's process state is set up once and never reset.
-}
module Pudu.Backend.Emit.Entry
  ( EmittedUnit (..)
  , EntryForm (..)
  , embeddedHeader
  , embeddedHeaderName
  , entrySection
  ) where

import Data.Set (Set)
import Data.Text (Text)
import qualified Data.Text as Text

data EntryForm = ExecutableEntry | EmbeddedEntry
  deriving stock (Eq, Show)

{-| @Backend.Emit.Unit — the C source, the runtime parts it selected, and the
    foreign library names and versions its declarations open, in first-seen order. -}
data EmittedUnit = EmittedUnit
  { emittedSource :: !Text
  , emittedParts :: !(Set Text)
  , emittedLibraries :: ![(Text, Maybe Text)]
  }
  deriving stock (Eq, Show)

embeddedEntryName :: Text
embeddedEntryName = "pudu_program_run"

-- | What the embedded entry answers to every call after the first.
alreadyStartedStatus :: Text
alreadyStartedStatus = "-1"

embeddedHeaderName :: FilePath
embeddedHeaderName = "pudu_program.h"

{-| The entry around its body lines, each path of which ends in `return`.
    `arguments` says the program reads its argument vector; `buffered` says
    the buffered output part is selected. -}
entrySection :: EntryForm -> Bool -> Bool -> [Text] -> [Text]
entrySection ExecutableEntry arguments _ body =
  opening <> ["  pudu_prepare_io();"] <> body <> ["}"]
 where
  opening
    | arguments =
        [ "int main(int count, char **values) {"
        , "  pudu_host_argument_count = count;"
        , "  pudu_host_argument_values = values;" ]
    | otherwise = ["int main(void) {"]
entrySection EmbeddedEntry arguments buffered body =
  ["static int pudu_program_main(int count, char **values) {"]
    <> stored <> ["  pudu_prepare_io();"] <> body <> ["}"]
    <> [ "#include <stdatomic.h>"
       , "static atomic_flag pudu_program_started = ATOMIC_FLAG_INIT;"
       , signature <> ";"
       , signature <> " {"
       , "  int pudu_status;"
       , "  if (atomic_flag_test_and_set(&pudu_program_started)) return " <> alreadyStartedStatus <> ";"
       , "  pudu_status = pudu_program_main(count, values);" ]
    <> ["  pudu_output_finish();" | buffered]
    <> [ "  (void)fflush(stdout);"
       , "  (void)fflush(stderr);"
       , "  return pudu_status;"
       , "}" ]
 where
  signature = "int " <> embeddedEntryName <> "(int count, char **values)"
  stored
    | arguments =
        [ "  pudu_host_argument_count = count;"
        , "  pudu_host_argument_values = values;" ]
    | otherwise = ["  (void)count;", "  (void)values;"]

{-| The header a host includes, naming each system library it must link. -}
embeddedHeader :: [Text] -> Text
embeddedHeader links = Text.unlines $
  [ "/* Generated by pudu: the entry of one Pudu program built as a library. */"
  , "#ifndef PUDU_PROGRAM_H"
  , "#define PUDU_PROGRAM_H"
  ]
    <> ["/* Link the host with: " <> Text.unwords links <> " */" | not (null links)]
    <> [ "#ifdef __cplusplus"
       , "extern \"C\" {"
       , "#endif"
       , "/* Returned by every call after the first: the runtime runs once. */"
       , "#define PUDU_PROGRAM_ALREADY_STARTED (" <> alreadyStartedStatus <> ")"
       , "/* Runs the program's main on the calling thread and returns its exit"
       , "   status once both standard streams are flushed and every foreign"
       , "   claim is released. A failure the program reports ends the process"
       , "   with status 1. Only the first call in a process runs the program. */"
       , "int " <> embeddedEntryName <> "(int count, char **values);"
       , "#ifdef __cplusplus"
       , "}"
       , "#endif"
       , "#endif"
       ]
